#!/bin/sh
# Builds a WSL rootfs tar: akmesh as a distribution one can import with
# "wsl --import" and then work in as a daily driver (acmesh-wsl).
#
# Why a tar and not a Dockerfile: "wsl --import <name> <dir> <tar>" takes a
# rootfs and nothing else. WSL brings /init, mounts /proc /sys /dev /mnt and
# writes /etc/resolv.conf and /etc/hosts itself - exactly the way the Ubuntu and
# the golang distro on this machine are set up (measured 25.11.2026: both carry
# only [boot] systemd or [automount], and both get their resolv.conf generated by
# WSL with "nameserver 10.255.255.254" plus the Windows search domains). So this
# script must NOT ship a resolver of its own; it ships a placeholder that says so.
#
# What the image carries:
#   /bin/akmesh        the static build, stripped
#   /bin/<name>        one symlink per command, names read from the binary
#   /usr/bin, /sbin, /usr/sbin, /usr/local/bin   symlinks to /bin, so a PATH a
#                      script inherited from anywhere still resolves
#   /etc/passwd, /etc/shadow, /etc/group          with a real user, not only root
#   /etc/wsl.conf      [user] default=<user>, so "wsl -d akmesh" opens as him
#   /etc/nsswitch.conf, /etc/profile, /etc/resolv.conf, /etc/hosts
#   /etc/ssl/certs/ca-certificates.crt            so curl and wget speak TLS
#   /home/<user>       with a .profile
#   /tmp (1777), /proc, /sys, /dev, /mnt, /run, /root, /var/log
#
# Usage:
#   ./scripts/make-wsl-image.sh                       # user akmesh, password akmesh
#   WSL_USER=anna WSL_PASSWORD=geheim ./scripts/make-wsl-image.sh  # any other name
#   ./scripts/make-wsl-image.sh --verify-only         # only check an existing rootfs
#
# The password is written as a SHA-512 crypt hash from our own mkpasswd; the
# plain text never enters the image.

set -eu

ROOT=$PWD
WSL_USER=${WSL_USER:-akmesh}
WSL_PASSWORD=${WSL_PASSWORD:-akmesh}
UID_USER=1000
GID_USER=1000
IMAGE_DIR="$ROOT/.build/wsl"
ROOTFS="$IMAGE_DIR/rootfs"
TAR="$ROOT/akmesh-wsl.tar"
BIN="$ROOT/akmesh"
VERIFY_ONLY=0
case "${1:-}" in
--verify-only) VERIFY_ONLY=1 ;;
esac

[ "$(id -u)" -eq 0 ] || {
	echo "make-wsl: run as root; the tar needs root ownership and the check uses chroot" >&2
	exit 2
}

# 1. Build. Static: a musl or glibc loader is not in the image, and a dynamic
# binary would die with "not found" - a message that looks like a missing file.
if [ "$VERIFY_ONLY" -eq 0 ]; then
	echo "make-wsl: building the static binary"
	CGO_ENABLED=0 ./scripts/build-bb.sh linux full
fi

[ -f "$BIN" ] || {
	echo "make-wsl: $BIN is missing; build it first" >&2
	exit 2
}

# 2. The rootfs, from scratch every time: a leftover symlink for a command that
# no longer exists would ship a broken name.
rm -rf "$IMAGE_DIR"
mkdir -p "$ROOTFS/bin" "$ROOTFS/etc/ssl/certs" "$ROOTFS/tmp" "$ROOTFS/proc" \
	"$ROOTFS/sys" "$ROOTFS/dev" "$ROOTFS/mnt" "$ROOTFS/run" "$ROOTFS/root" \
	"$ROOTFS/var/log" "$ROOTFS/home/$WSL_USER"

cp "$BIN" "$ROOTFS/bin/akmesh"
chmod 0755 "$ROOTFS/bin/akmesh"

# The names are what the binary answers to, not a list kept next to it.
NAMES=$(set +e; "$BIN" __akmesh_list_commands__ 2>&1 | sed -n 's/^ - //p')
COUNT=$(printf '%s\n' "$NAMES" | grep -c . || true)
[ "$COUNT" -gt 50 ] || {
	echo "make-wsl: only $COUNT command names read from the binary; the list changed shape" >&2
	exit 2
}
for name in $NAMES; do
	ln -sf akmesh "$ROOTFS/bin/$name"
done
echo "make-wsl: $COUNT names linked into /bin"

# A PATH like the one a script inherits (/usr/local/bin:...:/bin) must resolve
# inside this rootfs too, otherwise every apk install script fails on "mkdir not
# found" - the same reason akmesh-shell depends on the socket in split mode.
for d in usr/bin sbin usr/sbin usr/local/bin usr/local/sbin; do
	mkdir -p "$ROOTFS/$(dirname "$d")"
	ln -sfn /bin "$ROOTFS/$d"
done

# 3. Users. A distro with only root is not a daily driver: a normal session, a
# home directory, and a shell that belongs to a person.
HASH=$(set +e; "$BIN" mkpasswd -m sha-512 "$WSL_PASSWORD" 2>&1)
case "$HASH" in
'$6$'*) ;;
*)
	echo "make-wsl: mkpasswd did not return a sha-512 hash: $HASH" >&2
	exit 2
	;;
esac

cat > "$ROOTFS/etc/passwd" <<EOF
root:x:0:0:root:/root:/bin/sh
$WSL_USER:x:$UID_USER:$GID_USER:$WSL_USER:/home/$WSL_USER:/bin/sh
nobody:x:65534:65534:nobody:/nonexistent:/bin/sh
EOF
# Root stays locked: nothing in a WSL distro needs a root password, "wsl -u root"
# gets there, and a locked account is honest about it.
cat > "$ROOTFS/etc/shadow" <<EOF
root:!:::::::
$WSL_USER:$HASH:19000:0:99999:7:::
nobody:!:::::::
EOF
chmod 0400 "$ROOTFS/etc/shadow"
cat > "$ROOTFS/etc/group" <<EOF
root:x:0:
$WSL_USER:x:$GID_USER:
nobody:x:65534:
EOF

# 4. How WSL is told what to open. default= makes "wsl -d akmesh" land in the
# user's home instead of root; interop is on so that wsl.exe and Windows
# programmes still work from inside, as they do in the other two distros.
cat > "$ROOTFS/etc/wsl.conf" <<EOF
[user]
default=$WSL_USER

[automount]
# Off on purpose (measured 25.11.2026): WSL 3.0.5 cannot mount C: for this rootfs
# and says so at every start. It never calls the distro's /bin/mount while trying;
# a probe left there was not executed once. With the flag off the start is silent
# and honest - no empty /mnt/c that looks like a working drive. Turn it on again
# once our mount speaks drvfs, or to try a newer WSL.
enabled = false
mountFsTab = false
root = /mnt/

[interop]
enabled = true
appendWindowsPath = false

[network]
generateResolvConf = true
generateHosts = true
EOF

# WSL writes both files at boot from the Windows side. The content here is only
# what a session sees before that happens - and it says so, so nobody wonders why
# an edit disappears.
cat > "$ROOTFS/etc/resolv.conf" <<'EOF'
# Written by WSL at boot (nameserver 10.255.255.254, the Windows search domains).
# To keep a file of our own, set generateResolvConf = false in /etc/wsl.conf.
nameserver 1.1.1.1
EOF
cat > "$ROOTFS/etc/hosts" <<'EOF'
# Written by WSL at boot.
127.0.0.1	localhost
::1	localhost
EOF
cat > "$ROOTFS/etc/nsswitch.conf" <<'EOF'
hosts: files dns
EOF

cat > "$ROOTFS/etc/profile" <<EOF
# Read by an interactive "sh -l". PATH covers the directories a script from
# anywhere expects; they are all symlinks to /bin.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
PS1='\u@\h:\w\$ '
export PS1
[ -d "/home/$WSL_USER" ] && cd "/home/$WSL_USER" 2>/dev/null
EOF
cp "$ROOTFS/etc/profile" "$ROOTFS/home/$WSL_USER/.profile"

CA=""
for candidate in /etc/ssl/certs/ca-certificates.crt /etc/pki/tls/certs/ca-bundle.crt \
	/etc/ssl/cert.pem /etc/ca-certificates/extracted/tls-ca-bundle.pem; do
	if [ -f "$candidate" ]; then
		CA=$candidate
		break
	fi
done
if [ -n "$CA" ]; then
	cp "$CA" "$ROOTFS/etc/ssl/certs/ca-certificates.crt"
	echo "make-wsl: CA bundle from $CA ($(wc -c < "$ROOTFS/etc/ssl/certs/ca-certificates.crt") bytes)"
else
	echo "make-wsl: no CA bundle on this host; curl and wget will fail on https" >&2
fi

chmod 1777 "$ROOTFS/tmp"
chown "$UID_USER:$GID_USER" "$ROOTFS/home/$WSL_USER"
chmod 0755 "$ROOTFS/home/$WSL_USER"

# 5. Verify in the rootfs itself, before it becomes a tar: chroot is the closest
# thing to the first WSL start that does not need Windows.
echo "make-wsl: verifying the rootfs"
fail=0
check() {
	label=$1
	shift
	got=$(chroot "$ROOTFS" "$@" 2>&1) || true
	printf '  %-30s %s\n' "$label" "$(printf '%s' "$got" | tr '\n' ' ' | cut -c1-60)"
}

check "sh answers" /bin/sh -c 'echo shell-ok'
# Not "-lc": our sh parses "-l -c" but not the combined spelling, and this check
# would otherwise fail on a gap of the shell rather than on the image.
check "PATH from profile" /bin/sh -l -c 'echo $PATH'
check "cat /etc/passwd" /bin/sh -c "grep -c . /etc/passwd"
check "user in passwd" /bin/sh -c "grep '^$WSL_USER:' /etc/passwd"
check "home exists" /bin/sh -c "test -d /home/$WSL_USER && echo home-ok"
check "awk" /bin/sh -c 'echo "x 2" | awk "{print \$2}"'
check "grep" /bin/sh -c 'echo hallo | grep -c hallo'
check "ls /etc via akmesh" /bin/akmesh ls /etc
check "uname" /bin/akmesh uname -s
check "sh via symlink" /bin/sh -c 'echo via-symlink'

# The password must work for the user it was made for. su reads /etc/shadow the
# same way login does, so this checks the file and not only its format.
if printf '%s\n' "$WSL_PASSWORD" | chroot "$ROOTFS" /bin/akmesh su "$WSL_USER" -c 'id -un' > "$IMAGE_DIR/su.out" 2>&1; then
	printf '  %-30s %s\n' "su $WSL_USER with password" "$(tr -d '\n' < "$IMAGE_DIR/su.out" | cut -c1-60)"
	grep -qx "$WSL_USER" "$IMAGE_DIR/su.out" || { echo "make-wsl: su did not land on $WSL_USER" >&2; fail=1; }
else
	printf '  %-30s %s\n' "su $WSL_USER with password" "(failed: $(tr -d '\n' < "$IMAGE_DIR/su.out" | cut -c1-50))"
	fail=1
fi

[ "$fail" -eq 0 ] || { echo "make-wsl: the rootfs did not check out" >&2; exit 1; }

# 6. The tar. WSL imports it as the distro's filesystem; ownership has to be
# root's, and the file is deliberately uncompressed - "wsl --import" reads tar
# and tar.gz, and an uncompressed one can be inspected with tar tvf.
rm -f "$TAR"
tar -C "$ROOTFS" --owner=0 --group=0 -cf "$TAR" .
echo "make-wsl: $TAR ($(wc -c < "$TAR") bytes, $(tar tf "$TAR" | grep -c .) entries)"

cat <<EOF

Import it from Windows (the path must be a Windows path):

  wsl --import akmesh C:\\WSL\\akmesh $(wslpath -w "$TAR")
  wsl -d akmesh            # opens as $WSL_USER, password: the one given here

Remove it again - the image leaves nothing in the Windows registry behind:

  wsl --unregister akmesh

EOF
